P=Path('outputs/drive_analysis_20261003');j=json.loads((P/'torque_metrics.json').read_text());active=[r for r in j['routes'] if r['qualified']['seconds']];extra=[]
fig,axs=plt.subplots(len(active),2,figsize=(12,3.5*len(active)))
for ax,r in zip(axs,active):
 a=np.load(P/(r['route']+'.npz'));z=a['est'];q=np.load(P/(r['route']+'.qualified.npz'));t=(q['t']-q['t'][0])/60;m=q['mask'];tor=q['torque'];err=tor[:,7]-tor[:,6]
 ax[0].plot(t[::30],np.where(m,err,np.nan)[::30],lw=.5);ax[0].set_title(r['route']);ax[0].set_ylabel('Lateral acceleration error (m/s²)')
 te=(z[:,0]-q['t'][0])/60;ax[1].plot(te,z[:,6],label='Factor');ax[1].plot(te,z[:,8],label='Friction');ax[1].plot(te,z[:,7],label='Offset');ax[1].legend();ax[1].set_title('Filtered estimator parameters')
 for aa in ax:aa.set_xlabel('Minutes from first controller sample');aa.grid(alpha=.2)
 v=np.where((z[:,1]>0)&(z[:,2]>0))[0];e=a['eps_status'];c=a['cs'];ix=np.clip(np.searchsorted(c[:,0],e[:,0],side='right')-1,0,len(c)-1);cs=c[ix];sel=(e[:,1]==2)&(cs[:,2]>=10)&(e[:,0]>=cs[:,0])&(e[:,0]-cs[:,0]<.1)
 extra.append({'route':r['route'],'first_valid_estimate_min':float(te[v[0]]) if len(v) else None,'moving_status2_frames':int(sel.sum()),'driver_pressed_fraction':float(np.mean(cs[sel,4]>0)) if sel.any() else None})
